mapper.sql:
WITH VW_TASK AS ( /* 심사업무 오류건 목록 */
SELECT A.INPT_MST_SRNO , A.INPT_RCP_DT , A.INPT_ATMC_BIZ_DSCD , A.ACTL_FX_REFNO , A.AI_INPT_ACVT_CD , B.AI_INPT_ACVT_CD AS B_AI_INPT_ACVT_CD , A.AI_INSPE_ENO , A.AI_INPT_SNPE_ENO , A.INPT_ATMC_BIZ_DSCD AS AI_INPT_CMN_CD , RE.AI_INPT_ACVT_STS_CD , C.XPBY_COL_CTR_CUCD AS FC_CUNM , C.XPBY_COL_AM AS AI_INPT_BUY_AM , C.CSNO , C.CUS_KORL_NM AS AI_INPT_CUS_NM , (/* 심사자 직원명 */ SELECT AI_INPT_USER_NM FROM CSPD101TI WHERE AI_INPT_USER_ID = A.AI_INSPE_ENO AND ROWNUM = 1 ) AS AI_INSPE_ENM , (/* 결재자 직원명 */ SELECT AI_INPT_USER_NM FROM CSPD101TI WHERE AI_INPT_USER_ID = A.AI_INPT_SNPE_ENO AND ROWNUM = 1 ) AS AI_APPV_ENM , (/* 공통코드 (업무구분코드,그룹코드 150) */ SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '150' AND AI_INPT_CMN_CD = A.INPT_ATMC_BIZ_DSCD AND ROWNUM = 1 ) AS INPT_ATMC_BIZ_NM , (/* 공통코드 (액티비티코드,그룹코드 290) */ SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '290' AND AI_INPT_CMN_CD = A.AI_INPT_ACVT_CD AND ROWNUM = 1 ) AS INPT_ATVTNM FROM CSPD001TM A , (/* 상태변경 히스토리 상태변경 코드 */ SELECT INPT_MST_SRNO , AI_INPT_ACVT_CD FROM CSPD008TH /* 심사상태 변경이력 */ WHERE (AI_INPT_ACVT_CD = '80' OR AI_INPT_ACVT_CD = '40') GROUP BY INPT_MST_SRNO, AI_INPT_ACVT_CD
) B , ( SELECT INPT_MST_SRNO , AI_INPT_ACVT_STS_CD FROM CSPD008TH /* 심사상태 변경이력 */ WHERE AI_INPT_ACVT_STS_CD = '60' GROUP BY INPT_MST_SRNO, AI_INPT_ACVT_STS_CD )RE , (/* WINI DATA 수출 */ SELECT FX_ACNO AS ACTL_FX_REFNO , XPBY_COL_CTR_CUCD AS XPBY_COL_CTR_CUCD , XPBY_COL_AM AS XPBY_COL_AM , CUS_KORL_NM , CSNO , XPO_CVRG_MK_SQ AS FX_REFNO_SRNO FROM CSPD201TM UNION ALL /* WINI DATA 수입 */ SELECT FX_ACNO AS ACTL_FX_REFNO , TDOC_RCP_CUCD AS XPBY_COL_CTR_CUCD , TDOC_RCP_AM AS XPBY_COL_AM , CUS_KORL_NM , CSNO , TDOC_RCP_SRNO AS FX_REFNO_SRNO FROM CSPD202TM ) C WHERE A.INPT_MST_SRNO = B.INPT_MST_SRNO(+) AND A.INPT_MST_SRNO = RE.INPT_MST_SRNO (+) AND A.ACTL_FX_REFNO = C.ACTL_FX_REFNO(+) AND A.FX_REFNO_SRNO = C.FX_REFNO_SRNO(+)
AND A.AI_INPT_ACVT_CD IN ('140', '160') /* 액티비티 코드(290) - 140(Block), 160(승인) */
AND A.INPT_RCP_DT BETWEEN REPLACE(#{schSdate1}, '-', '') AND REPLACE(#{schEdate1}, '-', '')
AND A.INPT_ATMC_BIZ_DSCD = #{aiInptCmnCd}
AND ( AI_INSPE_ENO = #{inptBizAlctCrpeEno} OR AI_INPT_SNPE_ENO = #{inptBizAlctCrpeEno} )
AND A.ACTL_FX_REFNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
AND B.AI_INPT_ACVT_CD = '40'
AND RE.AI_INPT_ACVT_STS_CD = '60'
AND B.AI_INPT_ACVT_CD = '80'
AND C.CSNO = #{aiInptCusNo}
)

mapper.select:
	/* 수출수입심사현황 - 오류건 (4040) */
	/* RevertStatErrorMapper.selectListTotCnt */

	SELECT COUNT(*) totcnt
      FROM VW_TASK A
